package com.delivery.platform.catalog.common;
import com.delivery.platform.common.ApiException;import com.delivery.platform.catalog.cache.CatalogCache;import com.delivery.platform.identity.security.IdentityPrincipal;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Component;import java.util.*;
@Component public class CatalogSupport {private final JdbcClient db;private final CatalogCache cache;public CatalogSupport(JdbcClient db,CatalogCache cache){this.db=db;this.cache=cache;}
 public void merchant(IdentityPrincipal p,UUID id){owned("merchants",p,id,"MERCHANT_NOT_FOUND","Comercio no encontrado");}public void branch(IdentityPrincipal p,UUID id){owned("branches",p,id,"BRANCH_NOT_FOUND","Sucursal no encontrada");}public void category(IdentityPrincipal p,UUID id){owned("categories",p,id,"CATEGORY_NOT_FOUND","Categoría no encontrada");}public void product(IdentityPrincipal p,UUID id){owned("products",p,id,"PRODUCT_NOT_FOUND","Producto no encontrado");}
 private void owned(String table,IdentityPrincipal p,UUID id,String code,String msg){int n=db.sql("select count(*) from "+table+" where id=:i and tenant_id=:t").param("i",id).param("t",p.tenantId()).query(Integer.class).single();if(n==0)throw new ApiException(HttpStatus.NOT_FOUND,code,msg);}
 public void audit(IdentityPrincipal p,String action,String type,UUID id){db.sql("insert into audit_logs(tenant_id,user_id,action,entity_type,entity_id) values(:t,:u,:a,:y,:e)").param("t",p.tenantId()).param("u",p.userId()).param("a",action).param("y",type).param("e",id).update();cache.invalidate(p.tenantId());}
 public ApiException conflict(String code,String msg){return new ApiException(HttpStatus.CONFLICT,code,msg);}}
